import { SwitchProps as LDSwitchProps } from '@walmart-web/livingdesign-components';
import * as React from 'react';
/**
 * Switches are generally used to activate or deactivate (on/off) a specific setting.
 *  - {@link https://livingdesign.walmart.com/components/switch/ Guidelines}
 *
 * ### Content
 *
 * The Switch accepts label, isOn, onClick and disabled props.
 *
 * The Switch comes in two different states:
 *
 * - `enabled` (default)
 * - `disabled`
 *
 * Set the Switch's state using the 'disabled'  prop:
 *
 * ```tsx
 * const [isOn, setIsOn] = React.useState(false);
 * <Switch className="defaultSwitch" label="Switch" isOn={true} onClick={()=>setIsOn(!isOn)}/>
 * <Switch className="defaultSwitch" label="Switch" isOn={true} onClick={()=>setIsOn(!isOn)} disabled=true/>
 * ```
 * Set the Switch's label using label prop:
 *
 * ```tsx
 * const [isOn, setIsOn] = React.useState(false);
 * <Switch className="customClass" label="Switch label1" isOn={true} onClick={()=>setIsOn(!isOn)} />
 * <Switch className="customClass" label="Switch label2" isOn={true} onClick={()=>setIsOn(!isOn)} />
 * ```
 */
export type SwitchProps = LDSwitchProps;
export declare const Switch: React.FC<SwitchProps>;
